import { useEffect, useState } from "react";
import { Button, Table, Spinner, Alert } from "react-bootstrap";
import ModalForm from "../../components/ModalForm";

function ProveidorsList() {
  const [clients, setClients] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [selectedClient, setSelectedClient] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const token = localStorage.getItem('token');

  useEffect(() => {
    const fetchClients = async () => {
      try {
        setLoading(true);
        setError(null);

        const res = await fetch('http://localhost/api/clients', {
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
        });

        if (!res.ok) throw new Error('Error al obtenir els clients');

        const data = await res.json();
        setClients(data.dades || []);
      } catch (err) {
        console.error(err);
        setError('Error al obtenir els clients');
      } finally {
        setLoading(false);
      }
    };

    fetchClients();
  }, [token]);

  const handleEdit = (client) => {
    setSelectedClient(client);
    setShowModal(true);
  };

  const handleCloseModal = () => {
    setShowModal(false);
    setSelectedClient(null);
    // refresh list after edit/create
    (async () => {
      setLoading(true);
      try {
        const res = await fetch('http://localhost/api/clients', {
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
        });
        if (!res.ok) throw new Error('Error al obtenir els clients');
        const data = await res.json();
        setClients(data.dades || []);
      } catch (err) {
        console.error(err);
        setError('Error al obtenir els clients');
      } finally {
        setLoading(false);
      }
    })();
  };

  const handleDelete = async (clientId) => {
    if (!window.confirm('Segur que vols eliminar aquest client?')) return;
    try {
      const res = await fetch(`http://localhost/api/clients/${clientId}`, {
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
      });
      if (!res.ok) throw new Error('Error en eliminar');
      setClients(prev => prev.filter(c => c.id !== clientId));
    } catch (err) {
      console.error(err);
      alert('No s\u2019ha pogut eliminar el client');
    }
  };

  if (loading) {
    return (
      <div className="text-center mt-5">
        <Spinner animation="border" />
      </div>
    );
  }

  if (error) {
    return (
      <Alert variant="danger" className="mt-3">
        {error}
      </Alert>
    );
  }

  if (clients.length === 0) {
    return <p className="mt-3">No hi ha clients disponibles</p>;
  }

  return (
    <div className="mt-4">
      <h2>Llista de Clients</h2>

      <Table striped bordered hover className="mt-3">
        <thead>
          <tr>
            <th>ID</th>
            <th>Nom</th>
            <th>Correu</th>
            <th>Telèfon</th>
            <th>Data de Creació</th>
            <th>Accions</th>
          </tr>
        </thead>
        <tbody>
          {clients.map((client) => (
            <tr key={client.id}>
              <td>{client.id}</td>
              <td>{client.nom}</td>
              <td>{client.correu}</td>
              <td>{client.telefon}</td>
              <td>{new Date(client.created_at).toLocaleDateString('ca-ES')}</td>
              <td>
                <Button variant="warning" size="sm" className="me-2" onClick={() => handleEdit(client)}>
                  Editar
                </Button>
                <Button variant="danger" size="sm" onClick={() => handleDelete(client.id)}>
                  Eliminar
                </Button>
              </td>
            </tr>
          ))}
        </tbody>
      </Table>
      {showModal && (
        <ModalForm entity="clients" data={selectedClient} onClose={handleCloseModal} />
      )}
    </div>
  );
}

export default ProveidorsList;
